            transition: opacity 0.3s ease !important;
        }

        .twikoo-wrapper .tk-footer:hover {
            opacity: 0.5 !important;
        }

        .loading-indicator {
            text-align: center;
            padding: 60px 20px;
            color: var(--text-muted);
