                font-size: 0.95rem;
            }
            .twikoo-wrapper .tk-input .tk-field {
                font-size: 0.9rem !important;
                padding: 4px 2px !important;
            }
        }
    </style>
</head>
<body>
    <div class="page-wrapper">
        <div class="main-card">
            <div class="top-section">
                <!-- 顶部行：站点标题 + 主题按钮 -->
                <div class="top-row">
                    <div class="site-title">
                        <div id="lottie-animation" class="lottie-container"></div>
                        SYLVIE's Blog
                    </div>
                    <button id="theme-toggle" aria-label="切换主题">
                        <span id="theme-icon">🌙</span>
                    </button>
                </div>

                <div class="progress-container">
                    <div class="progress-bar" id="progressBar"></div>
                </div>

                <div class="nav-menu">
                    <a href="/" class="nav-link">首页</a>
                    <a href="/blog-custom.html" class="nav-link">日志</a>
                    <a href="/categories/" class="nav-link">分类</a>
                    <a href="/guestbook.html" class="nav-link active">留言</a>
                </div>
            </div>

            <!-- Twikoo 评论容器 -->
            <div class="twikoo-wrapper" id="twikoo-wrapper">
                <div id="loading-message" class="loading-indicator">加载留言板中...</div>
            </div>
        </div>
    </div>

    <script>
        // ===== 阅读进度条 =====
        window.addEventListener('scroll', function() {
            const winScroll = document.documentElement.scrollTop;
            const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            const scrolled = (winScroll / height) * 100;
            document.getElementById('progressBar').style.width = scrolled + '%';
        });

        // ===== Lottie 动画 =====
        function loadLottieAnimation() {
            const animationContainer = document.getElementById('lottie-animation');

            if (typeof lottie === 'undefined') {
                console.error('Lottie 库加载失败');
                animationContainer.style.backgroundColor = '#d19a66';
                animationContainer.style.borderRadius = '4px';
                return;
            }

            fetch('/images/message.json')
                .then(response => {
                    if (!response.ok) throw new Error('JSON 文件不存在');
                    return response.json();
                })
                .then(animationData => {
                    animationContainer.innerHTML = '';
                    lottie.loadAnimation({
                        container: animationContainer,
                        renderer: 'svg',
                        loop: true,
                        autoplay: true,
                        animationData: animationData
                    });
                    console.log('Lottie 动画加载成功');
                })
                .catch(error => {
                    console.error('动画加载失败:', error);
                    animationContainer.style.backgroundColor = '#d19a66';
                    animationContainer.style.borderRadius = '4px';
                });
        }

        // ===== Twikoo 评论加载 =====
        function loadTwikoo() {
            const wrapper = document.getElementById('twikoo-wrapper');

            wrapper.innerHTML = '<div id="loading-message" class="loading-indicator">加载留言板中...</div>';

            const script = document.createElement('script');
            script.src = 'https://cdn.jsdelivr.net/npm/twikoo@1.7.13/dist/twikoo.all.min.js';
            script.async = true;

            script.onload = function() {
                console.log('Twikoo 库加载成功');
                if (typeof twikoo !== 'undefined') {
                    twikoo.init({
                        envId: 'https://sylvie-2026.netlify.app/.netlify/functions/twikoo',
                        el: '#twikoo-wrapper',
                        lang: 'zh-CN',
                        path: window.location.pathname,
                    }).then(function() {
                        console.log('Twikoo 初始化成功');
                        const loadingMsg = document.getElementById('loading-message');
                        if (loadingMsg) loadingMsg.style.display = 'none';
                    }).catch(function(err) {
                        console.error('Twikoo 初始化失败:', err);
                        const loadingMsg = document.getElementById('loading-message');
                        if (loadingMsg) loadingMsg.textContent = '⚠️ 留言板加载失败，请稍后刷新重试';
                    });
                }
            };

            script.onerror = function() {
                console.error('Twikoo 库加载失败');
                const loadingMsg = document.getElementById('loading-message');
                if (loadingMsg) loadingMsg.textContent = '⚠️ 留言板加载失败，请检查网络连接';
            };

            wrapper.appendChild(script);
        }

        // ===== 主题切换功能 =====
        (function() {
            const toggleBtn = document.getElementById('theme-toggle');
            const iconSpan = document.getElementById('theme-icon');
            const htmlElement = document.documentElement;

            function applyTheme(theme) {
                if (theme === 'dark') {
                    htmlElement.classList.add('dark');
                    iconSpan.textContent = '☀️';
                } else {
                    htmlElement.classList.remove('dark');
                    iconSpan.textContent = '🌙';
                }
                localStorage.setItem('theme', theme);
            }

            function getCurrentTheme() {
                return htmlElement.classList.contains('dark') ? 'dark' : 'light';
            }

            function toggleTheme() {
                const current = getCurrentTheme();
                const next = current === 'dark' ? 'light' : 'dark';
                applyTheme(next);
            }

            function initTheme() {
                const stored = localStorage.getItem('theme');
                if (stored === 'dark' || stored === 'light') {
                    applyTheme(stored);
                    return;
                }
                const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
                applyTheme(prefersDark ? 'dark' : 'light');
            }

            if (toggleBtn) {
                toggleBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    toggleTheme();
                });
            }

            window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) {
                if (!localStorage.getItem('theme')) {
                    applyTheme(e.matches ? 'dark' : 'light');
                }
            });

            initTheme();
        })();

        // ===== 页面初始化 =====
        document.addEventListener('DOMContentLoaded', function() {
            loadLottieAnimation();
            loadTwikoo();
        });
    </script>
</body>
</html>

