        --error-color: #c0392b;
        --post-title: #2c3e50;
        --post-title-hover: #1a2a3a;
        --post-date: #7a8a9e;
        --progress-bg: #f2f4f8;
        --stat-text: #7a8a9e;
        --site-title: #2c3e50;
        --theme-border-color: rgba(44, 62, 80, 0.3);
        --theme-hover-bg: rgba(128, 128, 128, 0.12);
        /* 文章内容颜色 */
        --content-text: #2c3e50;
        --content-heading: #2c3e50;
        --content-blockquote-bg: rgba(44, 62, 80, 0.06);
        --content-blockquote-border: #808080;
        --content-code-bg: rgba(44, 62, 80, 0.06);
        --content-code-color: #c0392b;
        --content-pre-bg: rgba(44, 62, 80, 0.04);
        --content-link: #808080;
        --content-link-hover: #b8864a;
    }

    /* ===== 2. 深色模式 ===== */
    html.dark {
        --bg-body: #1e2024;
        --bg-wrapper: #1e2024;
        --bg-card: #25282e;
        --text-primary: #d4d8e0;
        --text-secondary: #c0c6d0;
        --text-muted: #a8b0be;
        --text-nav: #d4d8e0;
        --border-color: #3a3e45;
        --accent-color: #d4d8e0;
        --accent-hover: #e0aa77;
        --card-shadow: none;
        --loading-bg: rgba(255, 255, 255, 0.04);
        --error-color: #ff6b6b;
        --post-title: #d4d8e0;
        --post-title-hover: #ffffff;
        --post-date: #a8b0be;
        --progress-bg: #3a3e45;
        --stat-text: #a8b0be;
        --site-title: #d4d8e0;
        --theme-border-color: rgba(255, 255, 255, 0.25);
        --theme-hover-bg: rgba(209, 154, 102, 0.15);
        /* 深色文章内容颜色 */
        --content-text: #c8d0dc;
        --content-heading: #d4d8e0;
        --content-blockquote-bg: rgba(255, 255, 255, 0.04);
        --content-blockquote-border: #d4d8e0;
        --content-code-bg: rgba(255, 255, 255, 0.08);
        --content-code-color: #e0a080;
        --content-pre-bg: rgba(0, 0, 0, 0.3);
        --content-link: #d4d8e0;
        --content-link-hover: #e0aa77;
