    <script>
    // ===== 阅读进度条 =====
    window.addEventListener('scroll', function() {
        const winScroll = document.documentElement.scrollTop;
        const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        const scrolled = (winScroll / height) * 100;
        document.getElementById('progressBar').style.width = scrolled + '%';
    });

    // ===== 主题切换功能 =====
    (function() {
        const toggleBtn = document.getElementById('theme-toggle');
        const iconSpan = document.getElementById('theme-icon');
        const htmlElement = document.documentElement;

        function applyTheme(theme) {
            if (theme === 'dark') {
                htmlElement.classList.add('dark');
                iconSpan.textContent = '☀️';
            } else {
                htmlElement.classList.remove('dark');
                iconSpan.textContent = '🌙';
            }
            localStorage.setItem('theme', theme);
        }

        function getCurrentTheme() {
            return htmlElement.classList.contains('dark') ? 'dark' : 'light';
        }

        function toggleTheme() {
            const current = getCurrentTheme();
            const next = current === 'dark' ? 'light' : 'dark';
            applyTheme(next);
        }

        function initTheme() {
            const stored = localStorage.getItem('theme');
            if (stored === 'dark' || stored === 'light') {
                applyTheme(stored);
                return;
            }
            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            applyTheme(prefersDark ? 'dark' : 'light');
        }

        if (toggleBtn) {
            toggleBtn.addEventListener('click', function(e) {
                e.preventDefault();
                toggleTheme();
            });
        }

        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) {
            if (!localStorage.getItem('theme')) {
                applyTheme(e.matches ? 'dark' : 'light');
            }
        });

        initTheme();
    })();

    // ===== 文章加载逻辑 =====
    (function() {
        const container = document.getElementById('post-container');
        const titleElement = document.getElementById('articleTitle');
        const giscusWrapper = document.getElementById('giscus-wrapper');

        const urlParams = new URLSearchParams(window.location.search);
        const postPath = urlParams.get('path');

        if (!postPath) {
            container.innerHTML = `<div class="error-state">⚠️ 未指定文章路径<br><span style="font-size:0.9rem;">请使用 ?path=/文章/路径/ 访问</span></div>`;
            const titleText = titleElement.querySelector('.title-text');
            if (titleText) titleText.textContent = '未指定文章路径';
            return;
        }

        fetch('/content.json?t=' + Date.now())
            .then(res => res.json())
            .then(data => {
                let posts = Array.isArray(data) ? data : (data.posts || []);
                const urlPath = new URLSearchParams(window.location.search).get('path');

                let post = null;
                post = posts.find(p => p.path === urlPath || '/' + p.path === urlPath);
                if (!post) {
                    const urlFileName = urlPath.split('/').filter(Boolean).pop()?.replace(/\.html$/, '');
                    post = posts.find(p => {
                        const pFileName = p.path.split('/').filter(Boolean).pop()?.replace(/\.html$/, '');
                        return pFileName === urlFileName;
                    });
                }

                if (!post) {
                    container.innerHTML = `<div class="error-state"><h3>❌ 未找到文章</h3><p>路径: ${urlPath}</p></div>`;
                    const titleText = titleElement.querySelector('.title-text');
                    if (titleText) titleText.textContent = '未找到文章';
                    return;
                }

                document.title = `${post.title} · SYLVIE`;
                const titleText = titleElement.querySelector('.title-text');
                if (titleText) titleText.textContent = post.title;

                // 加载 Giscus 评论
                const term = post.path.replace(/^\//, '');
                giscusWrapper.innerHTML = '';
                const script = document.createElement('script');
                script.src = 'https://giscus.app/client.js';
                script.setAttribute('data-repo', 'chu-bao/my-blog-comments');
                script.setAttribute('data-repo-id', 'R_kgDORd4YvQ');
                script.setAttribute('data-category', 'Announcements');
                script.setAttribute('data-category-id', 'DIC_kwDORd4Yvc4C3pC6');
                script.setAttribute('data-mapping', 'specific');
                script.setAttribute('data-term', term);
                script.setAttribute('data-strict', '1');
                script.setAttribute('data-reactions-enabled', '0');
                script.setAttribute('data-emit-metadata', '0');
                script.setAttribute('data-input-position', 'bottom');
                script.setAttribute('data-theme', 'dark_dimmed');
                script.setAttribute('data-lang', 'zh-CN');
                script.setAttribute('crossorigin', 'anonymous');
                script.async = true;
                giscusWrapper.appendChild(script);

                // 获取标签
                let tags = [];
                if (post.tags) {
                    tags = post.tags.map(t => t.name || t);
                }

                // 获取内容
                let content = post.content || '<p>暂无文章内容</p>';

                // 生成标签HTML
                let tagsHtml = '';
                if (tags.length > 0) {
                    tagsHtml = tags.map(tag => `<span class="tag-item">#${tag}</span>`).join('');
                }

                // 生成分类HTML
                let categoryHtml = '';
                if (post.categories && post.categories.length > 0) {
                    const categoryLinks = post.categories.map((cat, index) => {
                        let catName = '';
                        if (typeof cat === 'string') {
                            catName = cat;
                        } else if (cat && typeof cat === 'object') {
                            catName = cat.name || cat.slug || '';
                        }
                        if (!catName) return '';
                        const encodedCategory = encodeURIComponent(catName);
                        return `
                            <span class="category-item">
                                <a href="/categories/?cat=${encodedCategory}" class="category-link">${catName}</a>
                                ${index < post.categories.length - 1 ? '<span class="category-separator">·</span>' : ''}
                            </span>
                        `;
                    }).join('');
                    if (categoryLinks) {
                        categoryHtml = `
                            <div class="category-container">
                                <span class="category-icon-wrapper">
                                    <img src="/images/label.png" alt="分类" class="category-icon">
                                </span>
                                ${categoryLinks}
                            </div>
                        `;
                    }
                }

                // 渲染文章内容
                container.innerHTML = `
                    <article>
                        <div class="post-content">${content}</div>
                        <footer class="article-footer">
                            ${categoryHtml}
                            <div class="post-tags">${tagsHtml}</div>
                        </footer>
                    </article>
                `;
            })
            .catch(error => {
                console.error('加载失败:', error);
                container.innerHTML = `<div class="error-state"><h3>⚠️ 加载失败</h3><p>${error.message}</p></div>`;
                const titleText = titleElement.querySelector('.title-text');
                if (titleText) titleText.textContent = '加载失败';
            });
    })();
    </script>
</body>
</html>

