            margin-top: 4px;
        }

        @media (max-width: 768px) {
            .categories-grid {
                grid-template-columns: 1fr;
                gap: 10px;
            }
        }

        .category-card {
            position: relative;
            border: none;
            border-radius: 10px;
            overflow: hidden;
            cursor: pointer;
            transition: all 0.25s ease;
            background-size: cover;
            background-position: center;
            height: 180px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
        }

        .category-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 8px 25px rgba(209, 154, 102, 0.25);
        }

        /* 每个分类不同的背景图片 */
        .category-card[data-category="学习"] {
            background-image: url('/images/life-bg.jpeg');
        }
        .category-card[data-category="技术"] {
            background-image: url('/images/tech-bg.jpg');
        }
        .category-card[data-category="旅行"] {
            background-image: url('/images/travel.jpeg');
        }
        .category-card[data-category="生活"] {
            background-image: url('/images/life.jpeg');
        }
        .category-card[data-category="摄影"] {
            background-image: url('/images/photo-bg.jpg');
        }
        .category-card[data-category="测试"] {
            background-image: url('/images/study-bg.jpeg');
        }
        .category-card[data-category="读书"] {
            background-image: url('/images/读书.jpg');
        }

        .category-card .card-content {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 16px 18px;
            background: linear-gradient(to top, var(--category-card-overlay) 0%, transparent 100%);
            transition: background 0.3s ease;
        }

        .category-card:hover .card-content {
            background: linear-gradient(to top, rgba(209, 154, 102, 0.3) 0%, transparent 100%);
        }

        .category-card .card-name {
            font-size: 0.85rem;
            font-weight: 500;
            color: var(--category-card-text);
            display: block;
            margin-bottom: 2px;
            letter-spacing: 0.3px;
        }

        .category-card .card-count {
            font-size: 0.75rem;
            color: rgba(255, 255, 255, 0.7);
        }

        .category-card .card-preview {
            font-size: 0.85rem;
            color: #ffffff;
            font-weight: 400;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            margin-top: 4px;
            opacity: 0.9;
        }

        /* ===== 文章列表 ===== */
        .posts-list {
            list-style: none;
            margin-top: 8px;
        }

        .post-item {
            display: flex;
            align-items: center;
            padding: 10px 0;
            gap: 16px;
            border-bottom: 1px solid var(--post-border);
            transition: border-color 0.3s ease;
        }

        .post-item:last-child {
            border-bottom: none;
        }

        .post-image {
            width: 50px;
            height: 50px;
            border-radius: 8px;
            overflow: hidden;
            background-color: var(--border-color);
            flex-shrink: 0;
            transition: background-color 0.3s ease;
        }

        .post-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .post-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            min-width: 0;
            justify-content: center;
            padding: 2px 0;
        }

        .post-title {
            font-size: 0.8rem;
            font-weight: 550;
            color: var(--post-title);
            text-decoration: none;
            transition: color 0.25s ease;
            word-break: break-word;
            margin-bottom: 4px;
            line-height: 1.4;
        }

        .post-title:hover {
            color: var(--post-title-hover);
        }

        .post-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
        }

        .post-date {
            font-size: 0.8rem;
            color: var(--post-date);
            transition: color 0.3s ease;
        }

        .post-meta .busuanzi_value_page_pv {
            color: #000000;
            background-color: var(--accent-color);
            padding: 0px 8px;
            border-radius: 10px;
            font-size: 0.7rem;
            font-weight: 500;
            line-height: 1.4;
            display: inline-block;
        }

        /* ===== 返回分类列表链接 ===== */
        .back-link {
            display: inline-block;
            margin-bottom: 16px;
            color: var(--accent-color);
            text-decoration: none;
            font-size: 0.9rem;
            transition: color 0.2s ease;
        }

        .back-link:hover {
            color: var(--accent-hover);
        }

        /* ===== 加载/错误/空状态 ===== */
        .loading-state, .error-state, .empty-state {
            text-align: center;
            padding: 40px 20px;
            background-color: var(--loading-bg);
            border-radius: 16px;
            color: var(--text-muted);
            margin-top: 12px;
            font-weight: 300;
            border: 1px solid var(--border-color);
            transition: background-color 0.4s ease, color 0.4s ease, border-color 0.4s ease;
            grid-column: 1 / -1;
        }

        .error-state {
            color: var(--error-color);
        }

        /* ===== 响应式 ===== */
        @media (max-width: 768px) {
            .page-wrapper {
                padding: 20px 16px;
            }
            .main-card {
                padding: 28px 24px;
            }
            .nav-menu {
                gap: 12px;
            }
            #theme-toggle {
                width: 28px;
                height: 28px;
                font-size: 0.95rem;
            }
            .category-card {
                height: 150px;
            }
            .post-item {
                gap: 12px;
            }
            .post-image {
                width: 48px;
                height: 48px;
            }
            .post-title {
                font-size: 0.9rem;
            }
        }
    </style>
</head>
<body>
