                            <path d="M287.08 621.93l32.12 8.61c0.96 0.26 1.52 1.24 1.27 2.19L283.26 771.6c-0.26 0.96-1.24 1.52-2.19 1.27l-32.12-8.61a1.795 1.795 0 0 1-1.27-2.19l37.21-138.87a1.79 1.79 0 0 1 2.19-1.27z" fill="currentColor"/>
                            <path d="M300.28 644.8l8.61-32.12c0.26-0.96-0.31-1.94-1.27-2.19l-138.87-37.21c-0.96-0.26-1.94 0.31-2.19 1.27l-8.61 32.12c-0.26 0.96 0.31 1.94 1.27 2.19l138.87 37.21c0.96 0.25 1.94-0.32 2.19-1.27z" fill="currentColor"/>
                            <path d="M473.41 520h33.26c0.99 0 1.79 0.8 1.79 1.79v392.42c0 0.99-0.8 1.79-1.79 1.79h-33.26c-0.99 0-1.79-0.8-1.79-1.79V521.79c0-0.99 0.8-1.79 1.79-1.79z" fill="currentColor"/>
                            <path d="M476.84 746.73l23.52-23.52c0.7-0.7 1.83-0.7 2.53 0l101.66 101.66c0.7 0.7 0.7 1.83 0 2.53l-23.52 23.52c-0.7 0.7-1.83 0.7-2.53 0L476.84 749.26c-0.7-0.7-0.7-1.83 0-2.53z" fill="currentColor"/>
                            <path d="M503.24 746.73l-23.52-23.52c-0.7-0.7-1.83-0.7-2.53 0L375.53 824.88c-0.7 0.7-0.7 1.83 0 2.53l23.52 23.52c0.7 0.7 1.83 0.7 2.53 0l101.66-101.66c0.7-0.71 0.7-1.84 0-2.54z" fill="currentColor"/>
