                            <path d="M693 418.07l-32.12-8.61a1.795 1.795 0 0 1-1.27-2.19l37.21-138.87c0.26-0.96 1.24-1.52 2.19-1.27l32.12 8.61c0.96 0.26 1.52 1.24 1.27 2.19L695.19 416.8c-0.26 0.96-1.24 1.52-2.19 1.27z" fill="currentColor"/>
