                        </svg>
                        SYLVIE's Blog
                    </div>
                    <button id="theme-toggle" aria-label="切换主题">
                        <span id="theme-icon">🌙</span>
                    </button>
                </div>

                <div class="progress-container">
                    <div class="progress-bar" id="progressBar"></div>
                </div>

                <div class="nav-menu">
                    <a href="/" class="nav-link">首页</a>
                    <a href="/blog-custom.html" class="nav-link">日志</a>
                    <a href="/categories/" class="nav-link active">分类</a>
                    <a href="/guestbook.html" class="nav-link">留言</a>
                </div>
            </div>

            <div id="dynamic-content">
                <div id="categories-container" class="categories-grid">
                    <div class="loading-state">📂 加载分类中...</div>
                </div>
            </div>
        </div>
    </div>

    <script>
        // ===== 阅读进度条 =====
        window.addEventListener('scroll', function() {
            const winScroll = document.documentElement.scrollTop;
            const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            const scrolled = (winScroll / height) * 100;
            document.getElementById('progressBar').style.width = scrolled + '%';
        });

        // ===== 获取URL参数 =====
        function getUrlParam(name) {
            const urlParams = new URLSearchParams(window.location.search);
            return urlParams.get(name);
        }

        // ===== 加载分类卡片 =====
        function loadCategories() {
            const container = document.getElementById('dynamic-content');

            fetch('/content.json?t=' + Date.now())
                .then(res => {
                    if (!res.ok) throw new Error('content.json 不存在');
                    return res.json();
                })
                .then(data => {
                    let posts = Array.isArray(data) ? data : (data.posts || []);

                    if (posts.length === 0) {
                        container.innerHTML = '<div class="error-state">暂无文章</div>';
                        return;
                    }

                    const categoriesMap = new Map();
                    posts.forEach(post => {
                        if (post.categories && post.categories.length > 0) {
                            post.categories.forEach(cat => {
                                let catName = typeof cat === 'string' ? cat : (cat.name || cat.slug || '');
                                if (!catName) return;
                                if (!categoriesMap.has(catName)) {
                                    categoriesMap.set(catName, []);
                                }
                                categoriesMap.get(catName).push(post);
                            });
                        }
                    });

                    if (categoriesMap.size === 0) {
                        container.innerHTML = '<div class="error-state">暂无分类</div>';
                        return;
                    }

                    const categoryOrder = ['生活', '技术', '骑行', '摄影', '测试', '学习', '读书'];
                    const sortedCategories = Array.from(categoriesMap.entries())
                        .sort((a, b) => {
                            const ia = categoryOrder.indexOf(a[0]), ib = categoryOrder.indexOf(b[0]);
                            if (ia !== -1 && ib !== -1) return ia - ib;
                            if (ia !== -1) return -1;
                            if (ib !== -1) return 1;
                            return a[0].localeCompare(b[0]);
                        });

                    let html = '<div class="categories-grid">';
                    sortedCategories.forEach(([catName, catPosts]) => {
                        const firstPost = catPosts[0];
                        const firstPostTitle = firstPost.title || '无标题';
                        html += `
                            <div class="category-card" data-category="${catName}" onclick="window.location.href='/categories/?cat=${encodeURIComponent(catName)}'">
                                <div class="card-content">
                                    <span class="card-name">${catName}</span>
                                    <span class="card-count">${catPosts.length} 篇</span>
                                    <div class="card-preview">${firstPostTitle}</div>
                                </div>
                            </div>
                        `;
                    });
                    html += '</div>';
                    container.innerHTML = html;
                })
                .catch(error => {
                    console.error('加载失败:', error);
                    container.innerHTML = `<div class="error-state"><h3>⚠️ 加载失败</h3><p>${error.message}</p></div>`;
                });
        }

        // ===== 加载分类详情（文章列表） =====
        function loadCategoryDetail(categoryName) {
            const container = document.getElementById('dynamic-content');

            fetch('/content.json?t=' + Date.now())
                .then(res => {
                    if (!res.ok) throw new Error('content.json 不存在');
                    return res.json();
                })
                .then(data => {
                    let posts = Array.isArray(data) ? data : (data.posts || []);

                    const categoryPosts = posts.filter(post => {
                        if (!post.categories) return false;
                        return post.categories.some(cat => {
                            const catName = typeof cat === 'string' ? cat : (cat.name || cat.slug || '');
                            return catName === categoryName;
                        });
                    });

                    if (categoryPosts.length === 0) {
                        container.innerHTML = `
                            <div>
                                <a href="/categories/" class="back-link">← 返回分类列表</a>
                                <div class="error-state"><h3>❌ 分类 "${categoryName}" 下暂无文章</h3></div>
                            </div>
                        `;
                        return;
                    }

                    categoryPosts.sort((a, b) => new Date(b.date) - new Date(a.date));

                    let postsHtml = '';
                    categoryPosts.forEach(post => {
                        let dateStr = '日期未知';
                        try {
                            const d = new Date(post.date);
                            dateStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
                        } catch(e) {}

                        const postPath = post.path.startsWith('/') ? post.path : '/' + post.path;
                        const articleLink = `/post-template.html?path=${encodeURIComponent(postPath)}`;
                        const thumbnail = post.thumbnail || '/images/default-post.jpg';

                        postsHtml += `
                            <li class="post-item">
                                <div class="post-image">
                                    <img src="${thumbnail}" alt="${post.title}" loading="lazy">
                                </div>
                                <div class="post-content">
                                    <a href="${articleLink}" class="post-title">${post.title || '无标题'}</a>
                                    <div class="post-footer">
                                        <span class="post-date">${dateStr}</span>
                                    </div>
                                </div>
                            </li>
                        `;
                    });

                    container.innerHTML = `
                        <div>
                            <a href="/categories/" class="back-link">← 返回分类列表</a>
                            <ul class="posts-list">${postsHtml}</ul>
                        </div>
                    `;
                })
                .catch(error => {
                    container.innerHTML = `
                        <div>
                            <a href="/categories/" class="back-link">← 返回分类列表</a>
                            <div class="error-state"><h3>⚠️ 加载失败</h3><p>${error.message}</p></div>
                        </div>
                    `;
                });
        }

        // ===== 主题切换功能 =====
        (function() {
            const toggleBtn = document.getElementById('theme-toggle');
            const iconSpan = document.getElementById('theme-icon');
            const htmlElement = document.documentElement;

            function applyTheme(theme) {
                if (theme === 'dark') {
                    htmlElement.classList.add('dark');
                    iconSpan.textContent = '☀️';
                } else {
                    htmlElement.classList.remove('dark');
                    iconSpan.textContent = '🌙';
                }
                localStorage.setItem('theme', theme);
            }

            function getCurrentTheme() {
                return htmlElement.classList.contains('dark') ? 'dark' : 'light';
            }

            function toggleTheme() {
                const current = getCurrentTheme();
                const next = current === 'dark' ? 'light' : 'dark';
                applyTheme(next);
            }

            function initTheme() {
                const stored = localStorage.getItem('theme');
                if (stored === 'dark' || stored === 'light') {
                    applyTheme(stored);
                    return;
                }
                const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
                applyTheme(prefersDark ? 'dark' : 'light');
            }

            if (toggleBtn) {
                toggleBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    toggleTheme();
                });
            }

            window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function(e) {
                if (!localStorage.getItem('theme')) {
                    applyTheme(e.matches ? 'dark' : 'light');
                }
            });

            initTheme();
        })();

        // ===== 页面初始化 =====
        (function() {
            const selectedCat = getUrlParam('cat');
            if (selectedCat) {
                loadCategoryDetail(selectedCat);
            } else {
                loadCategories();
            }
        })();
    </script>
</body>
</html>
